try {
  const items = await client.lRange('alice:mail:attachment_queue', 0, -1);
  if (items.length === 0) {
    return [{ json: { _empty: true } }];
  }
  // Items stay in alice:mail:attachment_queue until individually processed (lRem in
  // Code: Process Queue Item). This ensures unprocessed entries survive a time-limit
  // abort or a crash and are picked up on the next nightly run.
  await client.hIncrBy('alice:mail:attachment_run:stats', 'batches_run', 1);
  const results = [];
  for (const raw of items) {
    try {
      const parsed = JSON.parse(raw);
      results.push({ json: { ...parsed, _empty: false, _parse_error: false, _raw_json: raw } });
    } catch(e) {
      results.push({ json: { _empty: false, _parse_error: true, uid: null, attachments: [], _raw_json: raw } });
    }
  }
  return results;
} finally {
  await client.quit();
}

